<?php

namespace App\Http\Requests;

use App\Enums\TennisMode;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;

/**
 * POST /sessions/{session}/rounds
 *
 * With no body the next round is generated by the match type's
 * algorithm. With `matches` the host enters the round by hand — an
 * inter-club schedule, or a Mexicano round picked by the organiser.
 */
class StoreRoundRequest extends FormRequest
{
    /**
     * @return array<string, mixed>
     */
    public function rules(): array
    {
        return [
            // Lets a pre-written schedule skip slots (e.g. a men's-only
            // session with no match at 11:15).
            'round_number' => ['nullable', 'integer', 'min:1', 'max:999'],

            'matches' => ['sometimes', 'array', 'min:1', 'max:4'],
            'matches.*.court' => ['required_with:matches', 'integer', 'min:1', 'max:4'],
            // Per-match format override; null means the session's rule.
            'matches.*.tennis_mode' => ['nullable', Rule::enum(TennisMode::class)],
            'matches.*.team_a' => ['required_with:matches', 'array', 'size:2'],
            'matches.*.team_a.*' => ['required', 'uuid'],
            'matches.*.team_b' => ['required_with:matches', 'array', 'size:2'],
            'matches.*.team_b.*' => ['required', 'uuid'],
        ];
    }
}
